def _cards_global_gradients(kind: ThemeName) -> dict[str, GradientSpec]:
    """Gradientes dos shells compartilhados de Cards globais (blocos B/C)."""
    matrices = {
        ThemeName.LIGHT: {
            "card.study_action_surface_gradient": [(0.0, "#FBFCFE"), (1.0, "#FBFCFE")],
            "card.study_action_adaptive_surface_gradient": [(0.0, "#FAF9FF"), (1.0, "#FAF9FF")],
            "card.evolution_stat_surface_gradient": [(0.0, "#FFFFFF"), (1.0, "#FFFFFF")],
        },
        ThemeName.DARK: {
            "card.study_action_surface_gradient": [(0.0, "#152232"), (1.0, "#152232")],
            "card.study_action_adaptive_surface_gradient": [(0.0, "#152232"), (1.0, "#152232")],
            "card.evolution_stat_surface_gradient": [(0.0, "#111D2B"), (1.0, "#111D2B")],
        },
        ThemeName.FUTURISTIC: {
            "card.study_action_surface_gradient": [(0.0, "#EB0C1F2F"), (1.0, "#EB091624")],
            "card.study_action_adaptive_surface_gradient": [(0.0, "#EB0C1F2F"), (1.0, "#EB091624")],
            "card.evolution_stat_surface_gradient": [(0.0, "#0D2032"), (1.0, "#091725")],
        },
    }
    return {
        path: _palette_gradient(
            *stops,
            direction=GradientDirection(0.0, 0.0, 1.0, 1.0),
        )
        for path, stops in matrices[kind].items()
    }


